import xarray as xr
import numpy as np
from metpy.units import units
from metpy.interpolate import cross_section

# Create a dummy dataset with 'dBZ' units
data = xr.Dataset(
    {
        "reflectivity": (("lat", "lon"), np.random.rand(10, 10)),
    },
    coords={
        "lat": np.arange(10),
        "lon": np.arange(10),
    },
)
data.reflectivity.attrs["units"] = "dBZ"

start = (0, 0)
end = (1, 1)

try:
    cross = cross_section(data, start, end)
    print("Successfully created cross section")
except Exception as e:
    print(f"Caught expected exception: {e}")
    raise e
EOF
